const out = [];
for (const item of $input.all()) {
  const j = item.json;
  out.push({ json: {
    title: j.title || '',
    company: 'Forum n8n',
    url: j.link || j.guid || '',
    text: (j.contentSnippet || j.content || '').toString().slice(0, 2000),
    location: '',
    date: j.isoDate || j.pubDate || '',
    source: 'n8n Forum'
  }});
}
return out;

const html = ($input.first().json.data || '').toString();
const out = [];
const strip = s => (s || '').replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&#x27;|&#39;|&apos;/g, "'")
  .replace(/&quot;/g, '"').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
for (const block of html.split('<li>')) {
  const id = block.match(/urn:li:jobPosting:(\d+)/);
  if (!id) continue;
  const title = (block.match(/base-search-card__title[^>]*>([\s\S]*?)<\/h3>/) || [])[1];
  const company = (block.match(/base-search-card__subtitle[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/) || [])[1];
  const loc = (block.match(/job-search-card__location[^>]*>([\s\S]*?)<\/span>/) || [])[1];
  const date = (block.match(/<time[^>]*datetime="([^"]+)"/) || [])[1] || '';
  out.push({ json: {
    title: strip(title), company: strip(company),
    url: 'https://www.linkedin.com/jobs/view/' + id[1],
    text: '', location: strip(loc), date, source: 'LinkedIn'
  }});
}
return out;

const out = [];
for (const item of $input.all()) {
  const jobs = Array.isArray(item.json.jobs) ? item.json.jobs : [];
  for (const job of jobs) {
    out.push({ json: {
      title: job.jobTitle || '',
      company: job.companyName || '',
      url: job.url || '',
      text: (job.jobExcerpt || job.jobDescription || '').toString().replace(/<[^>]+>/g, ' ').slice(0, 2000),
      location: job.jobGeo || '',
      date: job.pubDate || '',
      source: 'Jobicy'
    }});
  }
}
return out;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const t = j.title || '';
  const idx = t.indexOf(':');
  out.push({ json: {
    title: idx > -1 ? t.slice(idx + 1).trim() : t,
    company: idx > -1 ? t.slice(0, idx).trim() : '',
    url: j.link || '',
    text: (j.contentSnippet || j.content || '').toString().slice(0, 2000),
    location: '', date: j.isoDate || j.pubDate || '', source: 'WeWorkRemotely'
  }});
}
return out;

// Filter v3 - Job Radar (buang tawaran jasa, senior, & lowongan basi)
const INCLUDE = /\b(n8n|automation|automate|workflow|integration|integrate|low-?code|no-?code|api|rpa)\b/i;
const EXCLUDE = /\b(commission[- ]only|unpaid)\b/i;
// tawaran jasa orang lain, bukan lowongan kerja
const SELLER = /^\s*[\[(]?\s*(for\s+hire|open\s+to\s+collab|looking\s+for\s+(remote\s+)?work|hire\s+me)|\$\s?\d+/i;
// posisi senior dibuang biar fokus entry/mid level
const SENIOR = /\b(senior|sr\.?|lead|principal|staff|head|director|vp|chief)\b/i;
const MAX_AGE_DAYS = 14; // hanya lowongan maksimal 14 hari
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.url) continue;
  const text = ((j.title || '') + ' ' + (j.text || ''));
  if (EXCLUDE.test(text)) continue;
  if (SELLER.test(j.title || '')) continue;
  if (SENIOR.test(j.title || '')) continue;
  const fresh = !j.date || (Date.now() - new Date(j.date).getTime()) <= MAX_AGE_DAYS * 864e5;
  if (!fresh) continue;
  if (j.source !== 'LinkedIn' && !INCLUDE.test(text)) continue;
  out.push({ json: j });
}
return out;

// Build Digest v3 - job radar (jatah per sumber + anti duplikat)
const items = $input.all().map(i => i.json);
const score = j => {
  const t = ((j.title || '') + ' ' + (j.text || '')).toLowerCase();
  const title = (j.title || '').toLowerCase();
  let s = 0;
  if (/\bn8n\b/.test(t)) s += 3;
  if (/(automation|automate|workflow)/.test(t)) s += 2;
  if (/(low-?code|no-?code|make\.com|zapier)/.test(t)) s += 1;
  if (/(remote|worldwide|anywhere|global)/.test(t + ' ' + (j.location || ''))) s += 1;
  if (j.date && (Date.now() - new Date(j.date).getTime()) <= 72 * 3600e3) s += 1;
  if (/(developer|engineer|builder|specialist|analyst|architect)/.test(title)) s += 1;
  return s;
};
// buang duplikat url dulu (jaring pengaman terakhir)
const seen = new Set();
const all = items
  .filter(j => !seen.has(j.url) && seen.add(j.url))
  .map(j => ({ ...j, score: score(j), first_seen: new Date().toISOString() }))
  .sort((a, b) => b.score - a.score);
// giliran per sumber: yang paling langka tampil duluan, biar sumber kecil tidak tenggelam
const QUOTA = 8, MAX = 15;
const bySource = {};
for (const j of all) {
  const s = j.source || 'Lainnya';
  (bySource[s] = bySource[s] || []).push(j);
}
const names = Object.keys(bySource).sort((a, b) => bySource[a].length - bySource[b].length);
const jobs = [];
for (let r = 0; r < QUOTA && jobs.length < MAX; r++) {
  for (const n of names) {
    if (jobs.length >= MAX) break;
    if (bySource[n][r]) jobs.push(bySource[n][r]);
  }
}
if (!jobs.length) return [];
// tampilan akhir diurutkan skor tertinggi dulu
jobs.sort((a, b) => b.score - a.score);
const lines = jobs.map((j, i) =>
  `${i + 1}. [${j.score}] ${j.title}${j.company ? ' | ' + j.company : ''} (${j.source})\n` +
  (j.location ? `   ${j.location}\n` : '') + `   ${j.url}`);
const today = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
const text = `🎯 Job Radar ${today}\n${jobs.length} lowongan baru:\n\n` + lines.join('\n\n');
return [{ json: { text, jobs } }];
